// static
bool StructTraits<::contextual_tasks::mojom::InjectedInput::DataView, ::contextual_tasks::mojom::InjectedInputPtr>::Read(
    ::contextual_tasks::mojom::InjectedInput::DataView input,
    ::contextual_tasks::mojom::InjectedInputPtr* output) {
  bool success = true;
  ::contextual_tasks::mojom::InjectedInputPtr result(::contextual_tasks::mojom::InjectedInput::New());
  
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadThumbnail(&result->thumbnail))
        success = false;
      if (success && !input.ReadIconId(&result->icon_id))
        success = false;
      if (success && !input.ReadFileToken(&result->file_token))
        success = false;
      if (success)
        result->supports_unimodal = input.supports_unimodal();
      if (success && !input.ReadQueryText(&result->query_text))
        success = false;
      if (success)
        result->submit_after_injection = input.submit_after_injection();
  *output = std::move(result);
  return success;
}


